/**
 * @param {number[]} salary
 * @return {number}
 */
var average = function(salary) {
    let sum = 0;
    let min = Infinity;
    let max = -Infinity;

    for (const s of salary) {
        sum += s;
        if (s < min) min = s;
        if (s > max) max = s;
    }

    return (sum - min - max) / (salary.length - 2);
};
