/**
 * @param {number[][]} grid
 * @param {number[][]} hits
 * @return {number[]}
 */
var hitBricks = function(grid, hits) {
    const m = grid.length;
    const n = grid[0].length;
    const total = m * n;
    const roof = total;

    const parent = new Int32Array(total + 1);
    const size = new Int32Array(total + 1);

    for (let i = 0; i <= total; i++) {
        parent[i] = i;
        size[i] = 1;
    }

    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };

    const union = (a, b) => {
        let rootA = find(a);
        let rootB = find(b);

        if (rootA === rootB) return;

        if (size[rootA] < size[rootB]) {
            const temp = rootA;
            rootA = rootB;
            rootB = temp;
        }

        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    };

    const id = (r, c) => r * n + c;

    const hitHadBrick = new Array(hits.length);

    for (let i = 0; i < hits.length; i++) {
        const [r, c] = hits[i];
        hitHadBrick[i] = grid[r][c] === 1;
        if (grid[r][c] === 1) {
            grid[r][c] = 0;
        }
    }

    const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];

    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] !== 1) continue;

            const cur = id(r, c);

            if (r === 0) {
                union(cur, roof);
            }

            if (r > 0 && grid[r - 1][c] === 1) {
                union(cur, id(r - 1, c));
            }

            if (c > 0 && grid[r][c - 1] === 1) {
                union(cur, id(r, c - 1));
            }
        }
    }

    const result = new Array(hits.length).fill(0);

    for (let i = hits.length - 1; i >= 0; i--) {
        if (!hitHadBrick[i]) continue;

        const [r, c] = hits[i];
        const before = size[find(roof)];

        grid[r][c] = 1;
        const cur = id(r, c);

        if (r === 0) {
            union(cur, roof);
        }

        for (const [dr, dc] of dirs) {
            const nr = r + dr;
            const nc = c + dc;

            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === 1) {
                union(cur, id(nr, nc));
            }
        }

        const after = size[find(roof)];
        result[i] = Math.max(0, after - before - 1);
    }

    return result;
};
```

