/**
 * @param {number} n
 * @return {number}
 */
var countVowelPermutation = function(n) {
    const MOD = 1000000007;

    let a = 1, e = 1, i = 1, o = 1, u = 1;

    for (let len = 2; len <= n; len++) {
        const nextA = (e + i + u) % MOD;
        const nextE = (a + i) % MOD;
        const nextI = (e + o) % MOD;
        const nextO = i % MOD;
        const nextU = (i + o) % MOD;

        a = nextA;
        e = nextE;
        i = nextI;
        o = nextO;
        u = nextU;
    }

    return (a + e + i + o + u) % MOD;
};
