class Fenwick {
    constructor(n) {
        this.n = n;
        this.tree = new Array(n + 2).fill(0);
    }

    add(index, delta) {
        for (let i = index; i <= this.n; i += i & -i) {
            this.tree[i] += delta;
        }
    }

    sum(index) {
        let res = 0;
        for (let i = index; i > 0; i -= i & -i) {
            res += this.tree[i];
        }
        return res;
    }

    findByOrder(k) {
        let idx = 0;
        let bit = 1;
        while ((bit << 1) <= this.n) bit <<= 1;

        for (; bit > 0; bit >>= 1) {
            const next = idx + bit;
            if (next <= this.n && this.tree[next] < k) {
                idx = next;
                k -= this.tree[next];
            }
        }

        return idx + 1;
    }
}

/**
 * @param {number} m
 * @param {number} k
 */
var MKAverage = function(m, k) {
    this.m = m;
    this.k = k;
    this.size = 0;
    this.queue = [];
    this.head = 0;
    this.maxVal = 100000;
    this.countBIT = new Fenwick(this.maxVal);
    this.sumBIT = new Fenwick(this.maxVal);
    this.totalSum = 0;
};

/** 
 * @param {number} num
 * @return {void}
 */
MKAverage.prototype.addElement = function(num) {
    this.queue.push(num);
    this.size++;

    this.countBIT.add(num, 1);
    this.sumBIT.add(num, num);
    this.totalSum += num;

    if (this.size > this.m) {
        const old = this.queue[this.head++];
        this.size--;

        this.countBIT.add(old, -1);
        this.sumBIT.add(old, -old);
        this.totalSum -= old;
    }
};

MKAverage.prototype.sumSmallest = function(cnt) {
    if (cnt <= 0) return 0;

    const val = this.countBIT.findByOrder(cnt);
    const countBefore = this.countBIT.sum(val - 1);
    const sumBefore = this.sumBIT.sum(val - 1);
    return sumBefore + (cnt - countBefore) * val;
};

/**
 * @return {number}
 */
MKAverage.prototype.calculateMKAverage = function() {
    if (this.size < this.m) return -1;

    const smallSum = this.sumSmallest(this.k);
    const sumWithoutLargestK = this.sumSmallest(this.m - this.k);
    const largeSum = this.totalSum - sumWithoutLargestK;

    const middleSum = this.totalSum - smallSum - largeSum;
    return Math.floor(middleSum / (this.m - 2 * this.k));
};

/** 
