/**
 * @param {number[]} nums
 * @return {number}
 */
var maxScore = function(nums) {
    const m = nums.length;
    const full = 1 << m;

    const gcd = (a, b) => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    };

    const g = Array.from({ length: m }, () => Array(m).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = i + 1; j < m; j++) {
            g[i][j] = gcd(nums[i], nums[j]);
        }
    }

    const bitCount = Array(full).fill(0);
    for (let mask = 1; mask < full; mask++) {
        bitCount[mask] = bitCount[mask >> 1] + (mask & 1);
    }

    const dp = Array(full).fill(0);

    for (let mask = 0; mask < full; mask++) {
        const used = bitCount[mask];
        if (used % 2 !== 0) continue;

        const op = used / 2 + 1;

        let first = -1;
        for (let i = 0; i < m; i++) {
            if ((mask & (1 << i)) === 0) {
                first = i;
                break;
            }
        }

        if (first === -1) continue;

        for (let j = first + 1; j < m; j++) {
            if ((mask & (1 << j)) === 0) {
                const newMask = mask | (1 << first) | (1 << j);
                dp[newMask] = Math.max(dp[newMask], dp[mask] + op * g[first][j]);
            }
        }
    }

    return dp[full - 1];
};
