 * @param {number} maxSize
 */
var CustomStack = function(maxSize) {
    this.maxSize = maxSize;
    this.stack = [];
    this.inc = [];
};

/** 
 * @param {number} x
 * @return {void}
 */
CustomStack.prototype.push = function(x) {
    if (this.stack.length === this.maxSize) return;

    this.stack.push(x);
    this.inc.push(0);
};

/**
 * @return {number}
 */
CustomStack.prototype.pop = function() {
    const n = this.stack.length;
    if (n === 0) return -1;

    const i = n - 1;
    const add = this.inc[i];

    if (i > 0) {
        this.inc[i - 1] += add;
    }

    this.inc.pop();
    return this.stack.pop() + add;
};

/** 
 * @param {number} k 
 * @param {number} val
 * @return {void}
 */
CustomStack.prototype.increment = function(k, val) {
    const n = this.stack.length;
    if (n === 0) return;

    const idx = Math.min(k, n) - 1;
    this.inc[idx] += val;
