 * @return {number}
 */
var maximumANDSum = function(nums, numSlots) {
    const n = nums.length;
    const pow3 = new Array(numSlots + 1).fill(1);

    for (let i = 1; i <= numSlots; i++) {
        pow3[i] = pow3[i - 1] * 3;
    }

    const totalStates = pow3[numSlots];
    const dp = new Array(totalStates).fill(-1);
    const count = new Array(totalStates).fill(0);

    for (let mask = 1; mask < totalStates; mask++) {
        count[mask] = count[Math.floor(mask / 3)] + (mask % 3);
    }

    dp[0] = 0;
    let answer = 0;

    for (let mask = 0; mask < totalStates; mask++) {
        if (dp[mask] === -1) continue;

        const idx = count[mask];
        if (idx === n) {
            answer = Math.max(answer, dp[mask]);
            continue;
        }

        for (let slot = 0; slot < numSlots; slot++) {
            const used = Math.floor(mask / pow3[slot]) % 3;

            if (used < 2) {
                const newMask = mask + pow3[slot];
                const value = dp[mask] + (nums[idx] & (slot + 1));
                dp[newMask] = Math.max(dp[newMask], value);
            }
        }
    }

    return answer;
};
