/**
 * @param {string[]} stickers
 * @param {string} target
 * @return {number}
 */
var minStickers = function(stickers, target) {
    const need = new Int8Array(26);
    for (const ch of target) need[ch.charCodeAt(0) - 97] = 1;

    const counts = [];
    const available = new Int8Array(26);

    for (const word of stickers) {
        const cnt = new Int8Array(26);
        let useful = false;

        for (const ch of word) {
            const idx = ch.charCodeAt(0) - 97;
            if (need[idx]) {
                cnt[idx]++;
                available[idx] = 1;
                useful = true;
            }
        }

        if (useful) counts.push(cnt);
    }

    for (const ch of target) {
        if (!available[ch.charCodeAt(0) - 97]) return -1;
    }

    const filtered = [];

    for (const cnt of counts) {
        let dominated = false;

        for (let i = filtered.length - 1; i >= 0; i--) {
            const other = filtered[i];
            let otherDominates = true;
            let cntDominates = true;

            for (let c = 0; c < 26; c++) {
                if (other[c] < cnt[c]) otherDominates = false;
                if (cnt[c] < other[c]) cntDominates = false;
            }

            if (otherDominates) {
                dominated = true;
                break;
            }

            if (cntDominates) {
                filtered.splice(i, 1);
            }
        }

        if (!dominated) filtered.push(cnt);
    }

    const sortedTarget = target.split('').sort().join('');
    const memo = new Map();
    memo.set('', 0);

    const letters = Array.from({ length: 26 }, (_, i) => String.fromCharCode(97 + i));

    const dfs = (remain) => {
        if (memo.has(remain)) return memo.get(remain);

        const remCnt = new Int8Array(26);
        for (const ch of remain) {
            remCnt[ch.charCodeAt(0) - 97]++;
        }

        const first = remain.charCodeAt(0) - 97;
        let best = Infinity;

        for (const sticker of filtered) {
            if (sticker[first] === 0) continue;

            const next = [];

            for (let c = 0; c < 26; c++) {
                const left = remCnt[c] - sticker[c];
                for (let k = 0; k < left; k++) {
                    next.push(letters[c]);
                }
            }

            const sub = dfs(next.join(''));
            if (sub !== -1) {
                best = Math.min(best, sub + 1);
            }
        }

        const ans = best === Infinity ? -1 : best;
        memo.set(remain, ans);
        return ans;
    };

    return dfs(sortedTarget);
};
