/**
 * @param {number} n
 * @param {number} firstPlayer
 * @param {number} secondPlayer
 * @return {number[]}
 */
var earliestAndLatest = function(n, firstPlayer, secondPlayer) {
    const memo = new Map();

    const dfs = (size, a, b) => {
        if (a + b === size + 1) return [1, 1];

        const key = size + "," + a + "," + b;
        if (memo.has(key)) return memo.get(key);

        const nextSize = Math.ceil(size / 2);
        let states = new Set();
        states.add("0,0");

        const contrib = (pos) => {
            if (pos < a) return [1, 0];
            if (pos > a && pos < b) return [0, 1];
            return [0, 0];
        };

        const applyOptions = (options) => {
            const nextStates = new Set();

            for (const state of states) {
                const [x, y] = state.split(",").map(Number);

                for (const [dx, dy] of options) {
                    nextStates.add((x + dx) + "," + (y + dy));
                }
            }

            states = nextStates;
        };

        for (let i = 1; i <= Math.floor(size / 2); i++) {
            const j = size + 1 - i;

            if (i === a || j === a || i === b || j === b) {
                applyOptions([[0, 0]]);
            } else {
                applyOptions([contrib(i), contrib(j)]);
            }
        }

        if (size % 2 === 1) {
            const mid = Math.floor(size / 2) + 1;
            applyOptions([contrib(mid)]);
        }

        let earliest = Infinity;
        let latest = -Infinity;

        for (const state of states) {
            const [x, y] = state.split(",").map(Number);
            const nextA = x + 1;
            const nextB = x + y + 2;

            const [e, l] = dfs(nextSize, nextA, nextB);
            earliest = Math.min(earliest, e + 1);
            latest = Math.max(latest, l + 1);
        }

        const result = [earliest, latest];
        memo.set(key, result);
        return result;
    };

    return dfs(n, firstPlayer, secondPlayer);
};
